create table if not exists teacher_profiles (id uuid primary key default gen_random_uuid(), user_id uuid unique not null references users(id) on delete cascade, establishment text, subjects text[], created_at timestamptz default now());
create table if not exists parent_links (id uuid primary key default gen_random_uuid(), parent_user_id uuid not null references users(id) on delete cascade, learner_user_id uuid not null references users(id) on delete cascade, consent_status text not null default 'pending', created_at timestamptz default now(), unique(parent_user_id, learner_user_id));
create table if not exists academic_levels (id uuid primary key default gen_random_uuid(), name text unique not null, country text not null default 'CI');
create table if not exists academic_classes (id uuid primary key default gen_random_uuid(), level_id uuid references academic_levels(id), name text not null, series text, unique(name, series));
create table if not exists curricula (id uuid primary key default gen_random_uuid(), class_id uuid references academic_classes(id), name text not null, school_year text, version text not null default '1', validation_status text not null default 'pending', provenance jsonb not null default '{}');
create table if not exists subjects (id uuid primary key default gen_random_uuid(), name text unique not null, code text unique);
create table if not exists competencies (id uuid primary key default gen_random_uuid(), curriculum_id uuid references curricula(id) on delete cascade, subject_id uuid references subjects(id), code text, title text not null, metadata jsonb not null default '{}');
create table if not exists chapters (id uuid primary key default gen_random_uuid(), competency_id uuid references competencies(id) on delete cascade, title text not null, position integer not null default 0);
create table if not exists lessons (id uuid primary key default gen_random_uuid(), chapter_id uuid references chapters(id) on delete cascade, title text not null, language text not null default 'fr', validation_status text not null default 'pending', version text not null default '1', provenance jsonb not null default '{}');
create table if not exists lesson_sections (id uuid primary key default gen_random_uuid(), lesson_id uuid not null references lessons(id) on delete cascade, section_type text not null, title text, position integer not null default 0);
create table if not exists lesson_steps (id uuid primary key default gen_random_uuid(), section_id uuid not null references lesson_sections(id) on delete cascade, step_type text not null, teacher_text text, board_blocks jsonb not null default '[]', avatar_command jsonb not null default '{}', source_ids uuid[] not null default '{}', position integer not null default 0);
create table if not exists exam_exercises (id uuid primary key default gen_random_uuid(), exam_paper_id uuid references exam_papers(id) on delete cascade, statement text not null, points numeric, difficulty text, competencies uuid[], provenance jsonb not null default '{}');
create table if not exists exam_corrections (id uuid primary key default gen_random_uuid(), exercise_id uuid not null references exam_exercises(id) on delete cascade, solution jsonb not null, correction_status text not null default 'proposal', source_url text, validated_by uuid references users(id), created_at timestamptz default now());
create table if not exists quizzes (id uuid primary key default gen_random_uuid(), lesson_id uuid references lessons(id) on delete cascade, title text not null, validation_status text not null default 'pending');
create table if not exists quiz_questions (id uuid primary key default gen_random_uuid(), quiz_id uuid not null references quizzes(id) on delete cascade, question text not null, choices jsonb, expected_answer jsonb not null, explanation text, points numeric default 1, source_ids uuid[] default '{}');
create table if not exists assignments (id uuid primary key default gen_random_uuid(), teacher_id uuid references users(id), title text not null, payload jsonb not null default '{}', due_at timestamptz, created_at timestamptz default now());
create table if not exists learner_attempts (id uuid primary key default gen_random_uuid(), learner_id uuid not null references users(id) on delete cascade, resource_type text not null, resource_id uuid, answer jsonb, score numeric, hints_used integer default 0, duration_seconds integer, created_at timestamptz default now());
create table if not exists learner_skill_states (id uuid primary key default gen_random_uuid(), learner_id uuid not null references users(id) on delete cascade, competency_id uuid not null references competencies(id), mastery numeric not null default 0 check (mastery between 0 and 1), model_version text, updated_at timestamptz default now(), unique(learner_id, competency_id));
create table if not exists course_sessions (id uuid primary key default gen_random_uuid(), learner_id uuid not null references users(id), lesson_id uuid references lessons(id), status text not null default 'active', started_at timestamptz default now(), ended_at timestamptz);
create table if not exists course_interactions (id uuid primary key default gen_random_uuid(), session_id uuid not null references course_sessions(id) on delete cascade, interaction_type text not null, payload jsonb not null default '{}', created_at timestamptz default now());
create table if not exists learning_events (id uuid primary key default gen_random_uuid(), learner_hash text not null, event_type text not null, payload jsonb not null default '{}', occurred_at timestamptz default now());
create table if not exists simulations (id uuid primary key default gen_random_uuid(), key text unique not null, title text not null, subject text not null, config jsonb not null default '{}', validation_status text not null default 'demo');
create table if not exists simulation_sessions (id uuid primary key default gen_random_uuid(), simulation_id uuid references simulations(id), learner_id uuid references users(id), state jsonb not null default '{}', started_at timestamptz default now(), ended_at timestamptz);
create table if not exists ai_conversations (id uuid primary key default gen_random_uuid(), learner_id uuid references users(id) on delete cascade, session_id uuid references course_sessions(id), created_at timestamptz default now());
create table if not exists ai_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references ai_conversations(id) on delete cascade, role text not null, content text not null, citations jsonb not null default '[]', created_at timestamptz default now());
create table if not exists voice_interactions (id uuid primary key default gen_random_uuid(), learner_id uuid references users(id), provider text not null, transcript text, confidence numeric, audio_object_path text, consent_status text, created_at timestamptz default now());
create table if not exists robot_events (id uuid primary key default gen_random_uuid(), session_id uuid references course_sessions(id), command jsonb not null, created_at timestamptz default now());
create table if not exists learner_recommendations (id uuid primary key default gen_random_uuid(), learner_id uuid not null references users(id) on delete cascade, recommendation_type text not null, payload jsonb not null, model_version text, created_at timestamptz default now(), expires_at timestamptz);
create table if not exists model_versions (id uuid primary key default gen_random_uuid(), name text not null, task text not null, version text not null, metadata jsonb not null default '{}', artifact_path text, status text not null default 'registered', created_at timestamptz default now(), unique(name, version));
create table if not exists model_predictions (id uuid primary key default gen_random_uuid(), model_version_id uuid references model_versions(id), subject_hash text, input_features jsonb not null, output jsonb not null, created_at timestamptz default now());
create table if not exists content_validations (id uuid primary key default gen_random_uuid(), resource_type text not null, resource_id uuid not null, status text not null, validator_id uuid references users(id), notes text, created_at timestamptz default now());
create table if not exists source_citations (id uuid primary key default gen_random_uuid(), document_id uuid references knowledge_documents(id), resource_type text not null, resource_id uuid not null, page_number integer, excerpt_hash text, created_at timestamptz default now());
create table if not exists web_research_results (id uuid primary key default gen_random_uuid(), query_hash text not null, url text not null, title text, excerpt text, domain text not null, confidence numeric, verified boolean default false, checked_at timestamptz default now());
create table if not exists feedback (id uuid primary key default gen_random_uuid(), user_id uuid references users(id) on delete set null, resource_type text, resource_id uuid, rating integer check (rating between 1 and 5), message text, created_at timestamptz default now());
create table if not exists notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references users(id) on delete cascade, title text not null, body text not null, read_at timestamptz, created_at timestamptz default now());
create table if not exists audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references users(id) on delete set null, action text not null, resource_type text, resource_id uuid, metadata jsonb not null default '{}', created_at timestamptz default now());

create index if not exists learner_attempts_learner_created_idx on learner_attempts(learner_id, created_at desc);
create index if not exists learning_events_hash_time_idx on learning_events(learner_hash, occurred_at desc);
create index if not exists ai_messages_conversation_idx on ai_messages(conversation_id, created_at);
create index if not exists audit_logs_actor_time_idx on audit_logs(actor_id, created_at desc);
